import sys

def min_ascii_delete_sum(s1, s2):
    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][0] = dp[i - 1][0] + ord(s1[i - 1])
    for j in range(1, m + 1):
        dp[0][j] = dp[0][j - 1] + ord(s2[j - 1])
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j] + ord(s1[i - 1]),
                               dp[i][j - 1] + ord(s2[j - 1]))
    return dp[n][m]

s1, s2 = sys.stdin.readline().split()
print(min_ascii_delete_sum(s1, s2))

import math

def cosine(x, y):
    if len(x) != len(y):
        raise ValueError('dimension mismatch')
    dot = sum(a * b for a, b in zip(x, y))
    nx = math.sqrt(sum(a * a for a in x))
    ny = math.sqrt(sum(b * b for b in y))
    if nx == 0.0 or ny == 0.0:
        return 0.0          # 零向量没有方向，约定返回 0
    return dot / (nx * ny)

print(round(cosine([1, 0, 1], [1, 1, 0]), 3))   # 0.5

def mean(xs):
    if not xs:
        raise ValueError('empty sample')
    return sum(xs) / len(xs)

def variance(xs, ddof=1):
    m = mean(xs)
    if len(xs) - ddof <= 0:
        raise ValueError('need more samples')
    return sum((x - m) ** 2 for x in xs) / (len(xs) - ddof)

