import torch

class GmmGatedAdapter(torch.nn.Module):
    def __init__(self, d_in, d_out, n_components=4, tau=0.0, temp=1.0):
        super().__init__()
        self.adapter = torch.nn.Linear(d_in, d_out, bias=False)
        self.means = torch.nn.Parameter(torch.randn(n_components, d_in))
        self.logvars = torch.nn.Parameter(torch.zeros(n_components, d_in))
        self.tau, self.temp = tau, temp

    def log_prob(self, x):
        # 对角高斯混合的对数密度，返回 [B]
        z = -0.5 * (((x[:, None, :] - self.means) ** 2) / self.logvars.exp()).sum(-1)
        return torch.logsumexp(z, dim=-1) - 0.5 * self.logvars.sum(-1).max()

    def gate(self, x):
        return torch.sigmoid((self.log_prob(x) - self.tau) / self.temp)

    def forward(self, x, base_out):
        return base_out + self.gate(x).unsqueeze(-1) * self.adapter(x)

import torch

def cfm_loss(v_theta, x0, x1, cond, t=None):
    """x0: source images [B,C,H,W]; x1: target-domain images; cond: instrument id."""
    b = x0.shape[0]
    if t is None:
        t = torch.rand(b, device=x0.device)
    shape = (-1,) + (1,) * (x0.dim() - 1)
    x_t = (1 - t.view(shape)) * x0 + t.view(shape) * x1   # 直线概率路径
    target = x1 - x0                                      # 路径上的常速度
    return ((v_theta(x_t, t, cond) - target) ** 2).mean()

def sample(v_theta, x0, cond, steps=32):
    x, dt = x0, 1.0 / steps
    for k in range(steps):
        x = x + dt * v_theta(x, torch.full((x.shape[0],), k * dt), cond)
    return x                                              # 沿 ODE 积分到目标域

import torch

class KVProjector(torch.nn.Module):
    '''学习把发送方 KV 映射到接收方空间，双方骨干均冻结。'''
    def __init__(self, d_src, d_dst):
        super().__init__()
        self.k_proj = torch.nn.Linear(d_src, d_dst)
        self.v_proj = torch.nn.Linear(d_src, d_dst)

    def forward(self, k_src, v_src):
        return self.k_proj(k_src), self.v_proj(v_src)

def calibration_loss(receiver, q, k_src, v_src, k_ref, v_ref, projector):
    k_hat, v_hat = projector(k_src, v_src)
    out_hat = receiver.attend(q, k_hat, v_hat)
    with torch.no_grad():
        out_ref = receiver.attend(q, k_ref, v_ref)
    return torch.nn.functional.mse_loss(out_hat, out_ref)

def contract_net(tasks, agents, value, cost, capable, priority=None):
    # 贪心合同网：按任务优先级逐个选净效用最大且可行的智能体
    order = sorted(range(len(tasks)),
                   key=lambda j: -(priority[j] if priority else value[j]))
    assignment, load = {}, {i: 0 for i in agents}
    for j in order:
        best, best_u = None, float('-inf')
        for i in agents:
            if not capable(i, j):
                continue
            u = value[j] - cost(i, j, load[i])      # 负载会抬高实际代价
            if u > best_u:
                best, best_u = i, u
        if best is not None:
            assignment[j] = best
            load[best] += 1
    return assignment, load

def spl(success, shortest, taken):
    """success: List[0/1]; shortest/taken: List[float] 路径长度"""
    assert len(success) == len(shortest) == len(taken) > 0
    total = 0.0
    for s, l, p in zip(success, shortest, taken):
        if s and l > 0:
            total += l / max(p, l)   # 成功且不绕路才拿满分
    return total / len(success)

