import sys


def edit_distance(a: str, b: str) -> int:
    """Levenshtein 距离：插入 / 删除 / 替换代价均为 1，滚动数组实现。"""
    if not a:
        return len(b)
    if not b:
        return len(a)
    if len(a) < len(b):
        a, b = b, a
    m = len(b)
    prev = list(range(m + 1))
    for i in range(1, len(a) + 1):
        cur = [i] + [0] * m
        for j in range(1, m + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            cur[j] = min(
                prev[j] + 1,
                cur[j - 1] + 1,
                prev[j - 1] + cost,
            )
        prev = cur
    return prev[m]


def main() -> None:
    lines = sys.stdin.read().splitlines()
    a = lines[0].strip() if len(lines) >= 1 else ""
    b = lines[1].strip() if len(lines) >= 2 else ""
    print(edit_distance(a, b))


if __name__ == "__main__":
    main()

class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def merge_two_sorted_lists(head1, head2):
    """合并两条递增单链表，返回合并后的头节点；只改指针，不新建节点。"""
    dummy = ListNode(0)          # 哨兵：统一「结果为空」与「已有尾节点」两种情况
    tail = dummy
    while head1 is not None and head2 is not None:
        if head1.val <= head2.val:   # 相等时只摘第一条链，保证不丢节点
            tail.next = head1
            head1 = head1.next
        else:
            tail.next = head2
            head2 = head2.next
        tail = tail.next             # 最常漏的一行：tail 必须跟着前移
    tail.next = head1 if head1 is not None else head2   # 剩余整段仍有序，O(1) 收尾
    return dummy.next


def build(vals):
    dummy = ListNode(0)
    cur = dummy
    for v in vals:
        cur.next = ListNode(v)
        cur = cur.next
    return dummy.next


def parse(text):
    """牛客格式 {1,3,5},{2,4,6} -> 两条链表；空段或 {} 表示空链表。"""
    parts = text.strip().split("},")
    if len(parts) != 2:
        raise ValueError("输入应形如 {1,3,5},{2,4,6}")

    def one(seg):
        seg = seg.strip().strip("{}").strip()
        if not seg:
            return None
        return build([int(x) for x in seg.split(",") if x.strip()])

    return one(parts[0]), one(parts[1])


def dump(head):
    vals = []
    while head is not None:
        vals.append(str(head.val))
        head = head.next
    return "{" + ",".join(vals) + "}"


if __name__ == "__main__":
    cases = [
        ("{1,3,5},{2,4,6}", "{1,2,3,4,5,6}"),
        ("{}, {}", "{}"),
        ("{-1,2,4},{1,3,4}", "{-1,1,2,3,4,4}"),
        ("{5,5},{5}", "{5,5,5}"),
        ("{}, {0}", "{0}"),
        ("{7},{1,2,3,4}", "{1,2,3,4,7}"),
    ]
    for text, want in cases:
        a, b = parse(text)
        got = dump(merge_two_sorted_lists(a, b))
        assert got == want, (text, got, want)
    print("all %d cases passed" % len(cases))

import sys
from functools import lru_cache


def solve_case(a: str, b: str) -> int:
    """A、B 各自保序归并成 C，返回所有 C 的最长回文子串长度的最大值。"""
    la, lb = len(a), len(b)

    @lru_cache(maxsize=None)
    def ok(i: int, j: int, k: int, l: int) -> bool:
        # A[i:j] 与 B[k:l] 拼起来是否为回文（左闭右开，允许其中一段为空）
        n = (j - i) + (l - k)
        if n <= 1:
            return True          # 空串与单字符都是回文（基例）
        if j - i >= 2 and a[i] == a[j - 1] and ok(i + 1, j - 1, k, l):
            return True          # 最外层一对都取自 A，必须各用 A 的一个字符
        if j - i >= 1 and l - k >= 1 and a[i] == b[l - 1] and ok(i + 1, j, k, l - 1):
            return True          # 左端取自 A、右端取自 B
        if j - i >= 1 and l - k >= 1 and b[k] == a[j - 1] and ok(i, j - 1, k + 1, l):
            return True          # 左端取自 B、右端取自 A
        if l - k >= 2 and b[k] == b[l - 1] and ok(i, j, k + 1, l - 1):
            return True          # 最外层一对都取自 B，必须各用 B 的一个字符
        return False

    best = 0
    for i in range(la + 1):
        for j in range(i, la + 1):
            for k in range(lb + 1):
                for l in range(k, lb + 1):
                    if (j - i) + (l - k) > best and ok(i, j, k, l):
                        best = (j - i) + (l - k)
    ok.cache_clear()
    return best


def main() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    t = int(data[0])
    pos = 1
    out = []
    for _ in range(t):
        a = data[pos] if pos < len(data) else ''
        b = data[pos + 1] if pos + 1 < len(data) else ''
        pos += 2
        out.append(str(solve_case(a, b)))
    sys.stdout.write('\n'.join(out) + '\n')


if __name__ == '__main__':
    main()

import sys


def is_pop_order(push_v, pop_v):
    """判断 pop_v 是否可能是 push_v 的弹出序列（题面保证 push_v 内元素互不相同）。"""
    if len(push_v) != len(pop_v):
        return False
    if sorted(push_v) != sorted(pop_v):
        return False          # 多重集不同，不可能是同一批元素的弹出顺序

    stack = []
    j = 0                     # pop_v 中下一个待匹配的弹出位置
    for value in push_v:
        stack.append(value)
        while stack and j < len(pop_v) and stack[-1] == pop_v[j]:
            stack.pop()       # 能弹就弹：晚弹会被新压入的元素永久埋住
            j += 1
    return j == len(pop_v) and not stack


def parse_seq(token):
    """把样例里的 [1,2,3,4,5] 形式解析成整数列表。"""
    token = token.strip().strip('[]')
    if not token:
        return []
    return [int(x) for x in token.replace(',', ' ').split()]


def main():
    data = ''.join(sys.stdin.read().split())
    if not data:
        return
    parts = data.split('],[')
    if len(parts) != 2:
        return
    push_v = parse_seq(parts[0])
    pop_v = parse_seq(parts[1])
    print('true' if is_pop_order(push_v, pop_v) else 'false')


if __name__ == '__main__':
    main()

import sys


def classify_triangle(a: int, b: int, c: int) -> str:
    """返回三角形的类型；不能构成非退化三角形时返回 'Not a triangle!'。"""
    sides = sorted((a, b, c))
    # 非退化三角形：三边均 > 0，且任意两边之和 > 第三边。
    # 排好序后，只需检查一条不等式：sides[0] + sides[1] > sides[2]。
    # 理由：sides[0] + sides[2] > sides[1] 等价于 sides[0] + sides[2] > sides[2]
    # 一定成立（因为 sides[2] > sides[1] 且 sides[0] > 0），另一条同理。
    if sides[0] <= 0 or sides[0] + sides[1] <= sides[2]:
        return "Not a triangle!"
    # 分类一步到位：不同边长的个数就是相等关系的个数。
    kinds = len({sides[0], sides[1], sides[2]})
    if kinds == 1:
        return "Equilateral triangle!"
    if kinds == 2:
        return "Isosceles triangle!"
    return "Ordinary triangle!"


def main() -> None:
    data = sys.stdin.read().split()
    if len(data) < 3:
        return
    out = []
    # 按每 3 个一组处理：单组数据是它的退化成 1 组的形式。
    for i in range(0, len(data) - 2, 3):
        try:
            sides = [int(data[i]), int(data[i + 1]), int(data[i + 2])]
        except ValueError:
            # 极端异常输入（非整数 token）直接跳过，保证主流程不抛异常。
            continue
        out.append(classify_triangle(sides[0], sides[1], sides[2]))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import sys


LOW, HIGH = 18.5, 23.9


def classify(weight, height):
    """BMI 落在 [LOW, HIGH] 输出 Normal，否则 Abnormal。

    写成乘法而非除法：18.5 <= w/h^2 <= 23.9 等价于 18.5*h^2 <= w <= 23.9*h^2，
    少一次除法舍入，边界（恰好 18.5 / 23.9）更不容易被浮点误判。
    """
    if height <= 0:
        return "Abnormal"
    if LOW * height * height <= weight <= HIGH * height * height:
        return "Normal"
    return "Abnormal"


def solve(text):
    out = []
    for line in text.splitlines():
        parts = line.split()
        if len(parts) < 2:
            continue
        weight, height = float(parts[0]), float(parts[1])
        out.append(classify(weight, height))
    return out


def main():
    text = sys.stdin.read()
    for verdict in solve(text):
        sys.stdout.write(verdict + "\n")


if __name__ == "__main__":
    main()

# 端侧推理峰值内存估算：为什么峰值会远超模型文件大小。
# 单选题结论：最可能让峰值显著超过模型文件的是
# 「中间激活、临时缓冲区和多分支并发执行」。
# 权重（模型文件）只是常驻的一份，激活与临时缓冲随 batch、序列长度、
# 算子实现（im2col、显式注意力矩阵）成倍放大；多分支并发时这些缓冲
# 还会同时驻留，峰值因此可以达到模型文件的数倍。纯标准库，可直接运行。


def weight_bytes(num_params, bits=8):
    # 模型文件大小的来源：参数量 x 量化位宽。bits 取 4/8/16/32。
    if num_params <= 0 or bits not in (4, 8, 16, 32):
        raise ValueError('num_params 必须为正，bits 取 4/8/16/32')
    return num_params * bits // 8


def kv_cache_bytes(batch, seq_len, layers, hidden, bits=8):
    # 自回归解码的 KV cache：2（K 和 V）x 层数 x batch x 序列 x 隐层。
    if min(batch, seq_len, layers, hidden) <= 0:
        raise ValueError('batch/seq_len/layers/hidden 都必须为正')
    return 2 * layers * batch * seq_len * hidden * (bits // 8)


def activation_bytes(batch, seq_len, hidden, layers, bits=8, fanout=2):
    # 中间激活：按每层一份 fanout 倍隐层的工作集估算。
    if min(batch, seq_len, hidden, layers) <= 0 or fanout < 1:
        raise ValueError('尺寸必须为正，fanout 至少为 1')
    return layers * batch * seq_len * hidden * fanout * (bits // 8)


def temp_buffer_bytes(batch, seq_len, hidden, im2col=False, attn_matrix=False, bits=8):
    # 算子临时缓冲：im2col 展开与显式 SxS 注意力矩阵是端侧最典型的两块。
    total = 0
    if im2col:
        total += batch * seq_len * hidden * 9 * (bits // 8)
    if attn_matrix:
        total += batch * seq_len * seq_len * (bits // 8)
    return total


def peak_memory(num_params, batch, seq_len, hidden, layers,
                bits=8, branches=1, im2col=False, attn_matrix=False):
    # 峰值 = 一份权重 + 每个并发分支各一份工作集 + 一份 KV cache。
    if branches < 1:
        raise ValueError('branches 至少为 1')
    weights = weight_bytes(num_params, bits)
    branch_ws = activation_bytes(batch, seq_len, hidden, layers, bits) + \
        temp_buffer_bytes(batch, seq_len, hidden, im2col, attn_matrix, bits)
    kv = kv_cache_bytes(batch, seq_len, layers, hidden, bits)
    peak = weights + branches * branch_ws + kv
    return {'weights': weights, 'branch_ws': branches * branch_ws,
            'kv_cache': kv, 'peak': peak, 'ratio_to_file': peak / weights}


def option_impact(option):
    # 逐个选项判定：只有 A 会成倍抬高峰值内存。
    table = {
        'A': '抬高：激活/临时缓冲随 batch*序列*隐层增长，多分支还并发多份',
        'B': '几乎无影响：输出类别数只决定最后一层的大小，是常数项',
        'C': '无影响：训练集规模属于训练阶段，端侧推理不读训练集',
        'D': '无影响：标签类别数不进入推理时的内存账',
    }
    return table.get(option.strip().upper(), '未知选项')


def main():
    # 例：1 亿参数、8bit 量化、batch=1、序列 512、隐层 1024、24 层、2 个并发分支。
    report = peak_memory(num_params=100000000, batch=1, seq_len=512,
                         hidden=1024, layers=24, bits=8,
                         branches=2, im2col=True, attn_matrix=True)
    mb = 1024 * 1024
    print('模型文件(权重): %.1f MB' % (report['weights'] / mb))
    print('分支工作集   : %.1f MB' % (report['branch_ws'] / mb))
    print('KV cache     : %.1f MB' % (report['kv_cache'] / mb))
    print('峰值内存     : %.1f MB' % (report['peak'] / mb))
    print('峰值/模型文件: %.2fx' % report['ratio_to_file'])
    for opt in 'ABCD':
        print(opt, option_impact(opt))
    assert report['ratio_to_file'] > 1.0, '峰值应当超过模型文件本身'
    # 边界：最小模型（1 参数、1 层、序列 1）也要有正的权重与合法分解。
    tiny = peak_memory(1, 1, 1, 1, 1, bits=32)
    assert tiny['peak'] >= tiny['weights'] > 0
    print('OK')


if __name__ == '__main__':
    main()

'''GSPO 长度归一化序列级重要性比率：方差对比实验（可直接运行）。

对应单选题的正确选项：降低逐 token 比率引入的高方差问题，改善训练稳定性。
本脚本用随机模拟证实两件事：
1. 逐 token 连乘比率 prod_t r_t 的抖动不随序列长度 L 收敛：对数比率之和的
   标准差按 sqrt(L) 增长，比率本身因此指数级抖动；
2. GSPO 的长度归一化序列级比率 s = exp(mean_t log r_t) 的标准差与 L 无关，
   实测约为单 token 波动除以 sqrt(L)。
运行：python gspo_ratio_variance.py
'''
import math
import random
import statistics

LOG_CLIP = 10.0


def token_log_ratios(rng, length, drift=0.0, noise=0.05):
    '''模拟一条序列上每个 token 的对数比率 log(pi_new/pi_old)。'''
    if length <= 0:
        raise ValueError('length 必须为正整数')
    vals = [rng.gauss(drift, noise) for _ in range(length)]
    return [max(-LOG_CLIP, min(LOG_CLIP, v)) for v in vals]


def token_level_ratio(log_ratios):
    '''逐 token 连乘：prod_t r_t = exp(sum_t log r_t)，长度越长越抖。'''
    if not log_ratios:
        raise ValueError('序列不能为空')
    return math.exp(sum(log_ratios))


def gspo_sequence_ratio(log_ratios):
    '''GSPO：s_i = (prod_t r_t) ** (1/L) = exp(mean_t log r_t)，几何平均即长度归一化。'''
    if not log_ratios:
        raise ValueError('序列不能为空')
    return math.exp(sum(log_ratios) / len(log_ratios))


def clipped(ratio, eps=3e-4):
    '''序列级对称裁剪：|s_i - 1| 超过 eps 的部分被截断，不再产生梯度。'''
    if not 0.0 < eps < 1.0:
        raise ValueError('eps 必须落在 (0, 1)')
    return min(1.0 + eps, max(1.0 - eps, ratio))


def variance_table(lengths, trials, seed=0):
    '''对每个长度重复 trials 次，返回 (长度, 连乘比率 std, GSPO 比率 std)。'''
    rng = random.Random(seed)
    rows = []
    for length in lengths:
        tok, gsp = [], []
        for _ in range(trials):
            lr = token_log_ratios(rng, length)
            tok.append(token_level_ratio(lr))
            gsp.append(gspo_sequence_ratio(lr))
        st, sg = statistics.pstdev(tok), statistics.pstdev(gsp)
        assert sg < st, '长度归一化应当降低比率抖动'
        rows.append((length, st, sg))
    return rows


def main():
    print('长度 逐token连乘std GSPO序列级std 缩减倍数')
    for length, st, sg in variance_table((16, 64, 256), trials=4000):
        print('%4d %14.4f %13.4f %10.1f' % (length, st, sg, st / sg))
    lr = token_log_ratios(random.Random(1), 1)
    assert math.isclose(gspo_sequence_ratio(lr), token_level_ratio(lr))
    print('L=1 时两者相等：', round(gspo_sequence_ratio(lr), 6))
    print('极端比率被裁剪到 1 加减 eps：', clipped(1.0 + 1e-3, 3e-4))
    try:
        gspo_sequence_ratio([])
    except ValueError as err:
        print('空序列报错：', err)


if __name__ == '__main__':
    main()

"""并查集（路径减半压缩 + 按秩合并）与 lc200 岛屿数量。

与人工 referenceSolution 同一算法路径：
  DSU.__init__ : p = list(range(n))、rank = [0]*n、count = n
  find         : 迭代式路径减半 self.p[x] = self.p[self.p[x]]
  union        : rank 小的根挂到 rank 大的根；等高才 rank[新根] += 1；成功合并才 count -= 1
  num_islands  : 二维坐标压成一维 id = r*C + c，每个 '1' 只与左、上邻居 union
纯 Python 标准库实现，不需要 torch / numpy（图形无关的数据结构题）。
本文件额外加了：下标/形状校验、connected() 便捷方法、以及一段可运行的 _self_test。
"""


class DSU:
    """路径减半压缩 + 按秩合并：单次操作均摊近似 O(alpha(n))。"""

    def __init__(self, n):
        if n < 0:
            raise ValueError('元素个数不能为负: %r' % (n,))
        self.p = list(range(n))     # 父指针；根满足 p[x] == x
        self.rank = [0] * n         # 树高（rank）上界，只增不减
        self.count = n              # 连通分量个数：初值 n，成功合并才减 1

    def find(self, x):
        """返回 x 所在树的根，顺手把路径减半。迭代写法，不吃递归深度。"""
        if not 0 <= x < len(self.p):
            raise IndexError('find 下标越界: %r' % (x,))
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]   # 指向祖父：走过的路径大约减半
            x = self.p[x]
        return x

    def union(self, a, b):
        """合并 a、b 所在集合；返回 True 表示这次真的合并了两个分量。"""
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False                    # 已在同一集合：count 不能再减
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra                 # 保证 ra 是更高的那棵树的根
        self.p[rb] = ra                     # 矮树挂到高树根下
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1              # 只有等高时新树高才 +1
        self.count -= 1
        return True

    def connected(self, a, b):
        return self.find(a) == self.find(b)


def num_islands(grid):
    """lc200：grid 是 R 行 C 列字符矩阵，'1' 陆地 / '0' 水；返回岛的个数。"""
    if not grid or not grid[0]:
        return 0                                # [] 与 [[]] 两个边界
    R, C = len(grid), len(grid[0])
    dsu = DSU(R * C)
    ones = 0
    for r in range(R):
        if len(grid[r]) != C:
            raise ValueError('第 %d 行 %d 列，首行 %d 列（锯齿矩阵）' % (r, len(grid[r]), C))
        for c in range(C):
            if grid[r][c] != '1':
                continue                        # '0' 不 union，也不计入 ones
            ones += 1
            for dr, dc in ((0, -1), (-1, 0)):   # 只看左、上：每条边只处理一次
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == '1':
                    dsu.union(r * C + c, nr * C + nc)
    roots = {dsu.find(r * C + c) for r in range(R) for c in range(C) if grid[r][c] == '1'}
    # 等价读数：每个 '0' 格子仍是独立分量，故 k = count - (R*C - ones)。
    assert len(roots) == dsu.count - (R * C - ones), 'k 的两种算法应当一致'
    return len(roots)


def _self_test():
    cases = [
        ([], 0),
        ([[]], 0),
        (['0'], 0),
        (['1'], 1),
        (['111', '010', '111'], 1),                  # 环：少写一个方向就会算成 5
        (['11000', '11000', '00100', '00011'], 3),   # lc200 官方样例
        (['111', '111', '111'], 1),
        (['101', '010', '101'], 5),                  # 对角不算连通
    ]
    for grid, want in cases:
        got = num_islands(grid)
        assert got == want, 'grid=%r 期望 %d 实得 %d' % (grid, want, got)

    dsu = DSU(10)
    assert dsu.find(0) == 0
    for i in range(1, 10):
        dsu.union(i - 1, i)                          # 0-1-2-...-9：全并成一个分量
    assert dsu.count == 1 and dsu.connected(0, 9)

    chain = DSU(6)
    for i in range(5):
        chain.p[i] = i + 1                           # 手工造 0->1->2->3->4->5 的链
    assert chain.find(0) == 5
    assert chain.p[0] != 1, '路径减半后 0 应指向祖父，而不是仍指向父节点'
    print('自测通过：%d 组岛屿用例 + DSU 连通性 + 路径减半验证' % len(cases))


if __name__ == '__main__':
    _self_test()

import random
from torch.utils.data import Dataset, DataLoader, Sampler


class CharTokenizer:
    """极简字符级分词器，只实现题目需要的那一种调用约定：
    tok(text, truncation=True, max_length=L) -> {"input_ids": [...]}
    真机换成 transformers 的 AutoTokenizer.from_pretrained(...) 即可，Dataset 无需改动。"""

    def __init__(self):
        self.vocab = {"<pad>": 0, "<unk>": 1}
        self.pad_id = 0
        self.unk_id = 1

    def _id(self, ch):
        if ch not in self.vocab:
            self.vocab[ch] = len(self.vocab)          # 动态扩表：保证任何字符都可编码
        return self.vocab[ch]

    def __call__(self, text, truncation=True, max_length=512):
        ids = [self._id(ch) for ch in text]
        if truncation:
            ids = ids[:max_length]                    # 先截断，再去 collate 里 pad
        return {"input_ids": ids or [self.unk_id]}    # 空串退化成一个 unk，避免长度 0


class MyDataset(Dataset):
    def __init__(self, samples, tokenizer, max_len=512):
        self.samples, self.tok, self.max_len = samples, tokenizer, max_len

    def __len__(self):
        return len(self.samples)

    def __getitem__(self, idx):
        s = self.samples[idx]
        ids = self.tok(s["text"], truncation=True, max_length=self.max_len)["input_ids"]
        return {"input_ids": ids, "label": s["label"]}

    def lengths(self):
        """给 BucketSampler 用的真实长度（截断后的 token 数）。"""
        return [min(len(self.tok(s["text"], truncation=True,
                                max_length=self.max_len)["input_ids"]), self.max_len)
                for s in self.samples]


def collate_fn(batch, pad_id=0):
    """关键：变长序列只 pad 到本 batch 最长，并生成 attention_mask；
    labels 侧的 padding 位置必须置 -100（cross_entropy 的 ignore_index）。"""
    if not batch:
        raise ValueError("empty batch：sampler / batch_size 配置有误，不要静默返回空张量")
    maxlen = max(len(b["input_ids"]) for b in batch)   # 本 batch 最长，不是全局最长
    input_ids, attn, labels = [], [], []
    for b in batch:
        ids = b["input_ids"]
        pad = maxlen - len(ids)
        input_ids.append(ids + [pad_id] * pad)
        attn.append([1] * len(ids) + [0] * pad)
        labels.append(ids + [-100] * pad)
    return {"input_ids": input_ids, "attention_mask": attn, "labels": labels}


class BucketSampler(Sampler):
    """按长度分桶：全局按长度升序 -> 每 batch_size 个切一桶 -> 打乱桶顺序。
    等长成批让 padding 浪费最小，桶间 shuffle 保住随机性（人工 pitfalls 第三条）。"""

    def __init__(self, lengths, batch_size, shuffle=True, shuffle_within_batch=False):
        if batch_size <= 0:
            raise ValueError("batch_size 必须为正")
        if not lengths:
            raise ValueError("lengths 为空：没有样本可分桶")
        order = sorted(range(len(lengths)), key=lambda i: lengths[i])
        self.batches = [order[i:i + batch_size] for i in range(0, len(order), batch_size)]
        self.shuffle = shuffle
        self.shuffle_within_batch = shuffle_within_batch

    def __iter__(self):
        bs = [b[:] for b in self.batches]        # 浅拷贝：不污染 self.batches，保证多轮可复现
        if self.shuffle:
            random.shuffle(bs)                   # 漏掉这步 = 每轮顺序完全相同
        for b in bs:
            if self.shuffle_within_batch:
                random.shuffle(b)                # 桶内再打乱（默认关闭，与人工实现一致）
            yield from b

    def __len__(self):
        return sum(len(b) for b in self.batches)


if __name__ == "__main__":
    random.seed(0)
    texts = ["深度学习", "a", "推荐系统与向量召回", "ab", "大模型对齐", "abc"]
    samples = [{"text": t, "label": i % 2} for i, t in enumerate(texts)]
    tok = CharTokenizer()
    ds = MyDataset(samples, tok, max_len=4)
    sampler = BucketSampler(ds.lengths(), batch_size=2)
    loader = DataLoader(ds, batch_size=2, sampler=sampler,
                        collate_fn=lambda b: collate_fn(b, pad_id=tok.pad_id),
                        num_workers=0, pin_memory=False)

    seen = 0
    for step, batch in enumerate(loader):
        lens = [sum(m) for m in batch["attention_mask"]]
        L = len(batch["input_ids"][0])
        assert all(len(row) == L for row in batch["input_ids"]), "batch 内必须等长"
        assert len(batch["labels"]) == len(batch["attention_mask"]) == len(batch["input_ids"])
        assert L == max(lens), "必须只 pad 到本 batch 最长"
        n_pad = sum(1 for row in batch["labels"] for x in row if x == -100)
        assert n_pad == sum(L - n for n in lens), "labels 的 pad 位必须恰好是 -100"
        seen += len(batch["input_ids"])
        print("step", step, "| L =", L, "| 有效长度", lens, "| 被忽略", n_pad)
    assert seen == len(ds), "sampler 必须恰好覆盖每个样本一次"
    print("ok: 覆盖", seen, "条样本，桶划分", [len(b) for b in sampler.batches])

# 联想 AI 岗笔试三块的可跑对照模板（纯标准库，无第三方依赖）。
# 1) 编程题「贪心只过 18%」：零钱兑换，贪心 vs 完全背包 DP 对拍，
#    反例 coins=[1,3,4]、amount=6（贪心 3 枚，最优 2 枚）。
# 2) 选择题 HMM：Viterbi 解码（对数域，避免连乘下溢）。
# 3) 选择题 LoRA：增量 (alpha/r)·B@A 与可训练参数量对比。
# 直接运行本文件会跑完全部断言并打印结果。
import math

INF = float('inf')


def greedy_min_coins(coins, amount):
    '''贪心：每次取不超过余额的最大面值；币制不成链式倍数时会错。'''
    if amount < 0:
        raise ValueError('amount 必须非负')
    rest, used = amount, 0
    for c in sorted(coins, reverse=True):
        if c <= 0:
            raise ValueError('面值必须为正整数')
        used += rest // c
        rest %= c
    return used if rest == 0 else -1


def dp_min_coins(coins, amount):
    '''完全背包：dp[a] 是凑出金额 a 的最少硬币数，无解返回 -1。'''
    if amount < 0:
        raise ValueError('amount 必须非负')
    if any(c <= 0 for c in coins):
        raise ValueError('面值必须为正整数')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return -1 if dp[amount] == INF else dp[amount]


def viterbi(obs, states, start_p, trans_p, emit_p):
    '''HMM 解码：返回 (最优状态序列, 对数概率)，全程取 log 防下溢。'''
    if not obs:
        return [], 0.0
    lg = lambda p: math.log(p) if p > 0 else -INF
    dp = {s: lg(start_p[s]) + lg(emit_p[s][obs[0]]) for s in states}
    back = []
    for t in range(1, len(obs)):
        prev, cur = {}, {}
        for s in states:
            best_s, best_v = None, -INF
            for p in states:
                v = dp[p] + lg(trans_p[p][s])
                if v > best_v:
                    best_s, best_v = p, v
            prev[s] = best_s
            cur[s] = best_v + lg(emit_p[s][obs[t]])
        back.append(prev)
        dp = cur
    last = max(states, key=lambda s: dp[s])
    path = [last]
    for prev in reversed(back):
        path.append(prev[path[-1]])
    path.reverse()
    return path, dp[last]


def lora_delta(w, a, b, alpha, r):
    '''LoRA 前向：W' = W + (alpha/r) * B @ A，A 是 [r,k]、B 是 [d,r]。'''
    if r <= 0 or alpha <= 0:
        raise ValueError('r 与 alpha 必须为正')
    d, k = len(w), len(w[0])
    if len(a) != r or len(a[0]) != k or len(b) != d or len(b[0]) != r:
        raise ValueError('形状必须是 A[r,k]、B[d,r]')
    scale = alpha / r
    return [[w[i][j] + scale * sum(b[i][t] * a[t][j] for t in range(r))
             for j in range(k)] for i in range(d)]


def _self_test():
    # 1) 贪心失效的形状：小样例过、全局最优挂
    assert greedy_min_coins([1, 3, 4], 6) == 3
    assert dp_min_coins([1, 3, 4], 6) == 2
    # 规范币制（每个面值都是前面面值的倍数）下贪心才等于最优
    canonical = [1, 5, 10, 50]
    for amount in range(0, 61):
        assert greedy_min_coins(canonical, amount) == dp_min_coins(canonical, amount)
    # 边界：无解、金额 0、面值非法
    assert dp_min_coins([3, 5], 1) == -1 and dp_min_coins([3, 5], 0) == 0
    for bad in ([0], [-1, 2]):
        try:
            dp_min_coins(bad, 4)
            raise AssertionError('非法面值没有被拦下')
        except ValueError:
            pass
    # 2) HMM：观测 [a, b] 下最优状态序列应为 ['H', 'L']
    states = ['H', 'L']
    start = {'H': 0.6, 'L': 0.4}
    trans = {'H': {'H': 0.7, 'L': 0.3}, 'L': {'H': 0.4, 'L': 0.6}}
    emit = {'H': {'a': 0.9, 'b': 0.1}, 'L': {'a': 0.2, 'b': 0.8}}
    path, score = viterbi(['a', 'b'], states, start, trans, emit)
    assert path == ['H', 'L'] and score < 0
    assert viterbi([], states, start, trans, emit) == ([], 0.0)
    # 3) LoRA：alpha/r 缩放、B 零初始化让起点等于原模型、参数量对比
    w = [[1.0, 0.0], [0.0, 1.0]]
    got = lora_delta(w, [[1.0, 0.0]], [[2.0], [3.0]], alpha=2, r=1)
    assert got == [[5.0, 0.0], [6.0, 1.0]]
    assert lora_delta([[7.0]], [[1.0]], [[0.0]], alpha=8, r=1) == [[7.0]]
    d = k = 4096
    rr = 8
    assert rr * k + d * rr == 65536 and d * k == 256 * (rr * k + d * rr)
    print('贪心 coins=[1,3,4] amount=6 ->', greedy_min_coins([1, 3, 4], 6),
          '| DP ->', dp_min_coins([1, 3, 4], 6))
    print('Viterbi 状态序列 =', path, '对数概率 =', round(score, 4))
    print('LoRA 可训练参数 =', rr * k + d * rr, '全参 =', d * k, '压缩倍数 = 256')


if __name__ == '__main__':
    _self_test()
    print('all self-tests passed')

'''1 主 + 3 子多智能体编排的最小可运行模型（纯标准库）。

链路：边界互斥注册 -> 按依赖分波并行 -> 契约校验 -> 带反馈重试 -> 汇总 -> 金标评测。
第 4 个子智能体的取舍：k 个 agent 两两接口是 O(k^2)，新增一个必须先拿出它独占的边界，
否则路由歧义、协调成本上升，吞吐却不变。
'''
import statistics
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field


class BoundaryError(RuntimeError):
    '''任务无人认领，或两个子智能体争抢同一类边界。'''


@dataclass
class Task:
    tid: str
    kind: str
    payload: dict = field(default_factory=dict)
    deps: tuple = ()


class SubAgent:
    kind, name, cost = '', '', 1

    def accepts(self, task):
        return task.kind == self.kind

    def run(self, task):
        raise NotImplementedError


class Retriever(SubAgent):
    kind, name, cost = 'retrieve', '检索子', 3

    def run(self, task):
        rows = [int(v) for v in task.payload.get('rows', [])]
        if not rows:
            raise ValueError('检索子拿到空数据源')
        drift = 1 if task.payload.get('poison') and not task.payload.get('feedback') else 0
        return {'rows': rows, 'n': len(rows) + drift}


class Analyzer(SubAgent):
    kind, name, cost = 'analyze', '分析子', 2

    def run(self, task):
        parts = task.payload.get('inputs') or []
        for p in parts:
            if 'rows' not in p:
                raise ValueError('上游产物缺少 rows 字段')
        rows = [v for p in parts for v in p['rows']]
        if not rows:
            raise ValueError('分析子拿到空数据，拒绝产出')
        return {'mean': round(statistics.fmean(rows), 3),
                'p95': sorted(rows)[min(len(rows) - 1, int(0.95 * len(rows)))],
                'n': len(rows)}


class Writer(SubAgent):
    kind, name, cost = 'write', '写作子', 2

    def run(self, task):
        m = (task.payload.get('inputs') or [{}])[0]
        return {'report': '样本 %s 条，均值 %s，P95 %s' % (m['n'], m['mean'], m['p95'])}


CONTRACT = {'retrieve': {'rows': list, 'n': int},
            'analyze': {'mean': float, 'p95': int, 'n': int},
            'write': {'report': str}}
RULES = {'retrieve': lambda o: [] if o['n'] == len(o['rows']) else ['n 与 rows 长度不一致'],
         'analyze': lambda o: [] if o['n'] > 0 else ['样本数必须为正'],
         'write': lambda o: [] if str(o['report']).strip() else ['报告为空']}


def validate(kind, out):
    if not isinstance(out, dict):
        return ['%s 的输出不是 dict' % kind]
    errs = ['缺少或类型错误的字段 %s' % k for k, t in CONTRACT[kind].items()
            if not isinstance(out.get(k), t)]
    return errs or RULES[kind](out)


class Orchestrator:
    def __init__(self, agents, max_retry=1):
        self.max_retry, self.retries, self.violations = int(max_retry), 0, []
        self.agents, self.by_kind = list(agents), {}
        for a in agents:
            if a.kind in self.by_kind:
                raise BoundaryError('%s 与 %s 的边界重叠：%s' % (a.name, self.by_kind[a.kind], a.kind))
            self.by_kind[a.kind] = a.name

    def route(self, task):
        for a in self.agents:
            if a.accepts(task):
                return a
        raise BoundaryError('任务 %s 的 kind=%s 没有归口' % (task.tid, task.kind))

    def _one(self, task, upstream):
        agent, feedback = self.route(task), None
        for attempt in range(self.max_retry + 1):
            payload = dict(task.payload, inputs=upstream, feedback=feedback)
            try:
                out = agent.run(Task(task.tid, task.kind, payload, task.deps))
                errs = validate(task.kind, out)
            except Exception as exc:
                out, errs = None, ['执行异常：%s' % exc]
            if not errs:
                return out
            feedback = errs
            if attempt < self.max_retry:
                self.retries += 1
                self.violations.append((task.tid, errs))
        raise BoundaryError('%s 重试 %d 次仍不合契约：%s' % (task.tid, self.max_retry, feedback))

    def run_plan(self, tasks):
        pending, done, waves = {t.tid: t for t in tasks}, {}, []
        while pending:
            ready = [t for t in pending.values() if all(d in done for d in t.deps)]
            if not ready:
                raise ValueError('依赖成环或指向不存在的上游')
            waves.append([t.tid for t in ready])
            with ThreadPoolExecutor(max_workers=len(ready)) as pool:
                futs = {t.tid: pool.submit(self._one, t, [done[d] for d in t.deps])
                        for t in ready}
            for t in ready:
                done[t.tid] = futs[t.tid].result()
                pending.pop(t.tid)
        return done, waves


COST = {'retrieve': 3, 'analyze': 2, 'write': 2}


def build_plan(a, b, poison=False):
    return [Task('t1', 'retrieve', {'rows': a, 'poison': poison}),
            Task('t2', 'retrieve', {'rows': b}),
            Task('t3', 'analyze', {}, ('t1', 't2')),
            Task('t4', 'write', {}, ('t3',))]


def makespan(waves, plan):
    kinds = {t.tid: t.kind for t in plan}
    serial = sum(COST[kinds[i]] for w in waves for i in w)
    parallel = sum(max(COST[kinds[i]] for i in w) for w in waves)
    return serial, parallel


GOLD = [('双源合并', [3, 9, 27, 81], [5], False, 5, 25.0, 81),
        ('单条样本', [7], [7], False, 2, 7.0, 7),
        ('脏数据自愈', [1, 2, 3, 4, 5], [7], True, 6, 3.667, 7)]


def evaluate(cases):
    passed, retries = 0, 0
    for name, a, b, poison, n, mean, p95 in cases:
        orc = Orchestrator([Retriever(), Analyzer(), Writer()], max_retry=1)
        done, _ = orc.run_plan(build_plan(a, b, poison))
        hit = (done['t3']['n'], done['t3']['mean'], done['t3']['p95']) == (n, mean, p95)
        passed, retries = passed + int(hit), retries + orc.retries
        print('[%s] %s 重试=%d' % ('PASS' if hit else 'FAIL', name, orc.retries))
    return passed, len(cases), retries


if __name__ == '__main__':
    plan = build_plan([3, 9, 27, 81], [5])
    orc = Orchestrator([Retriever(), Analyzer(), Writer()], max_retry=1)
    done, waves = orc.run_plan(plan)
    assert waves == [['t1', 't2'], ['t3'], ['t4']], waves
    assert done['t4']['report'] == '样本 5 条，均值 25.0，P95 81', done['t4']
    assert orc.retries == 0 and orc.violations == []
    print('波次:', waves, '串行/并行耗时:', makespan(waves, plan))
    bad = 0
    try:
        Orchestrator([Retriever(), Analyzer(), Analyzer()])
    except BoundaryError:
        bad = 1
    assert bad == 1, '同类边界必须报冲突'
    try:
        orc.route(Task('t9', 'translate'))
    except BoundaryError:
        bad = 2
    assert bad == 2, '无归口任务必须报错'
    hard = Orchestrator([Retriever(), Analyzer(), Writer()], max_retry=0)
    try:
        hard.run_plan(build_plan([1, 2, 3, 4, 5], [7], poison=True))
    except BoundaryError:
        bad = 3
    assert bad == 3, '不允许重试时脏数据必须让整条链路失败'
    print('评测:', evaluate(GOLD))

'''KV Cache 显存估算：MHA / GQA / MQA / MLA 与 KV 量化。

公式主线（MHA/GQA/MQA）：bytes = 2 * L * H_kv * d_head * S * B * BPE
其中 2 是 K 与 V 两份；MLA 把 2 * H_kv * d_head 换成 d_c + d_rope
（压缩潜向量 + 解耦的 RoPE 分量）；BPE 是每元素字节数，由位宽与量化分组决定。
运行：python kv_cache_calc.py   只依赖标准库，模型参数都是可替换的示例量级。
'''

GIB = 1024 * 1024 * 1024


class AttnConfig:
    '''一种注意力结构的 KV 缓存形状：非 MLA 用 kv_heads * d_head，MLA 用潜维。'''

    def __init__(self, name, layers, kv_heads=None, head_dim=None,
                 latent_dim=0, rope_dim=0, heads=None):
        if layers <= 0:
            raise ValueError('layers 必须为正，实际 %r' % (layers,))
        if latent_dim > 0:
            if rope_dim < 0:
                raise ValueError('rope_dim 不能为负')
        elif not (kv_heads and head_dim):
            raise ValueError('非 MLA 结构必须同时给出 kv_heads 与 head_dim')
        self.name, self.layers = name, layers
        self.kv_heads, self.head_dim = kv_heads, head_dim
        self.latent_dim, self.rope_dim = latent_dim, rope_dim
        self.heads = heads

    @property
    def is_mla(self):
        return self.latent_dim > 0

    def elements_per_token(self):
        '''每 token 每层缓存多少元素（与精度无关，是估算的不变量）。'''
        if self.is_mla:
            return self.latent_dim + self.rope_dim
        return 2 * self.kv_heads * self.head_dim

    def describe(self):
        if self.is_mla:
            return 'MLA d_c=%d + d_rope=%d' % (self.latent_dim, self.rope_dim)
        kind = 'MHA' if self.heads and self.kv_heads == self.heads else 'GQA/MQA'
        return '%s H_kv=%d d_head=%d' % (kind, self.kv_heads, self.head_dim)


def bytes_per_element(bits, group_size=0, scale_bytes=2):
    '''BPE = bits / 8 + scale_bytes / group_size；group_size=0 表示无分组也无 scale。'''
    if bits <= 0:
        raise ValueError('bits 必须为正')
    if group_size < 0 or scale_bytes < 0:
        raise ValueError('group_size / scale_bytes 不能为负')
    bpe = bits / 8.0
    if group_size:
        bpe += scale_bytes / group_size
    return bpe


def kv_cache_bytes(cfg, seq_len, batch=1, bits=16, group_size=0):
    '''整段 KV 缓存字节数；seq_len 或 batch 为 0 时返回 0.0。'''
    if seq_len < 0 or batch < 0:
        raise ValueError('seq_len / batch 不能为负')
    if seq_len == 0 or batch == 0:
        return 0.0
    per_token = cfg.layers * cfg.elements_per_token() * bytes_per_element(bits, group_size)
    return per_token * seq_len * batch


def max_sequences(cfg, seq_len, budget_bytes, bits=16, group_size=0):
    '''显存预算内能同时驻留几条该长度的序列（向下取整）。'''
    one = kv_cache_bytes(cfg, seq_len, bits=bits, group_size=group_size)
    if one <= 0:
        raise ValueError('单序列占用为 0，无法估算并发数')
    return int(budget_bytes // one)


def human(n):
    for unit in ('B', 'KiB', 'MiB'):
        if abs(n) < 1024:
            return '%.2f %s' % (n, unit)
        n /= 1024.0
    return '%.2f GiB' % n


def main():
    seq = 4096
    mha = AttnConfig('MHA 基线', layers=60, kv_heads=128, head_dim=128, heads=128)
    gqa = AttnConfig('GQA 8 组', layers=60, kv_heads=8, head_dim=128, heads=128)
    mqa = AttnConfig('MQA 单组', layers=60, kv_heads=1, head_dim=128, heads=128)
    mla = AttnConfig('MLA 潜向量', layers=60, latent_dim=512, rope_dim=64)

    print('每 token 每层元素数：MHA=%d GQA=%d MQA=%d MLA=%d' % (
        mha.elements_per_token(), gqa.elements_per_token(),
        mqa.elements_per_token(), mla.elements_per_token()))
    for cfg in (mha, gqa, mqa, mla):
        print('%-10s %-22s 每 token %10s | S=%d 单序列 %10s' % (
            cfg.name, cfg.describe(), human(kv_cache_bytes(cfg, 1)),
            seq, human(kv_cache_bytes(cfg, seq))))

    ratio = kv_cache_bytes(mha, 1) / kv_cache_bytes(mla, 1)
    print('MLA 相对同层数同头数 MHA：%.2f 倍压缩，降 %.1f%%' % (ratio, 100 * (1 - 1 / ratio)))

    for bits, group in ((16, 0), (8, 0), (4, 64), (4, 128)):
        print('量化 bits=%2d group=%3d -> BPE=%.5f | MLA 每 token %s' % (
            bits, group, bytes_per_element(bits, group),
            human(kv_cache_bytes(mla, 1, bits=bits, group_size=group))))

    v3 = AttnConfig('V3 量级', layers=61, latent_dim=512, rope_dim=64)
    ctx = 131072
    print('61 层 MLA、S=%d：每 token %s，单序列 %s' % (
        ctx, human(kv_cache_bytes(v3, 1)), human(kv_cache_bytes(v3, ctx))))
    print('40 GiB 预算下并发 128K 序列数：%d' % max_sequences(v3, ctx, 40 * GIB))

    assert mha.elements_per_token() == 2 * 128 * 128 == 32768
    assert gqa.elements_per_token() == 2 * 8 * 128
    assert mla.elements_per_token() == 512 + 64
    assert kv_cache_bytes(mha, 1) == 2 * 128 * 128 * 60 * 2
    assert kv_cache_bytes(mla, 1) == (512 + 64) * 60 * 2
    assert abs(ratio - 512 / 9) < 1e-9
    assert bytes_per_element(4, 64) == 0.5 + 2 / 64
    assert bytes_per_element(4, 128) < bytes_per_element(4, 64)
    assert kv_cache_bytes(gqa, seq, bits=8) == kv_cache_bytes(gqa, seq, bits=16) / 2
    assert kv_cache_bytes(mla, 0) == 0.0 and kv_cache_bytes(mla, 10, batch=0) == 0.0
    assert max_sequences(v3, ctx, 40 * GIB) == 4
    print('all assertions passed')


if __name__ == '__main__':
    main()

'''100 盏灯与 100 个学生：暴力模拟与「约数奇偶性」推理互相印证。'''


def toggle_simulation(n):
    '''O(n log n) 暴力：第 i 个学生翻转所有 i 的倍数，返回最终亮灯数。'''
    if n < 0:
        raise ValueError('n 必须非负')
    lamps = [False] * (n + 1)          # 下标 0 占位，灯编号 1..n，全关
    for i in range(1, n + 1):
        for j in range(i, n + 1, i):   # j = i, 2i, 3i, ... 即 i 的倍数
            lamps[j] = not lamps[j]    # 切换 = 翻转
    return sum(lamps)


def count_open_by_squares(n):
    '''O(√n) 结论：灯 j 被翻「j 的约数个数」次，只有完全平方数为奇数次。'''
    if n < 0:
        raise ValueError('n 必须非负')
    lo, hi = 0, n + 1                  # 二分求 floor(sqrt(n))，避免浮点误差
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo                          # 亮灯就是 1²,2²,...,lo²


def divisor_count(j):
    '''暴力数 j 的正约数个数，用来验证「翻转次数 = 约数个数」。'''
    return sum(1 for d in range(1, j + 1) if j % d == 0)


if __name__ == '__main__':
    assert toggle_simulation(0) == 0 and count_open_by_squares(0) == 0
    assert toggle_simulation(1) == 1 and count_open_by_squares(1) == 1
    for n in range(1, 401):            # 小规模对拍：模拟结果 == floor(sqrt(n))
        assert toggle_simulation(n) == count_open_by_squares(n), n
    for j in range(1, 61):             # 翻转奇偶性 == 是否完全平方数
        root = count_open_by_squares(j)
        assert (divisor_count(j) % 2 == 1) == (root * root == j), j
    print('100 盏灯最后亮着 %d 盏：1, 4, 9, 16, 25, 36, 49, 64, 81, 100'
          % toggle_simulation(100))

'''视觉原语（point/box/polygon/mask）与文本 token 的统一混合序列建模。

三件事：坐标离散化把几何回归变成分类；文本与原语块拼成一条序列做自回归
p(x)=prod_t p(x_t | x 的前缀)；用规范形与约束解码保证几何合法、可反解。
纯标准库实现，直接运行，末尾自带断言自测。
'''
import math

BINS = 1000
TAGS = {'point': '<point>', 'box': '<box>', 'polygon': '<polygon>', 'mask': '<mask>'}
CLOSE = '</prim>'
ARITY = {'point': 2, 'box': 4}


def quantize(c, bins=BINS):
    '''把 [0,1] 的连续坐标映射成桶号；越界 clamp，NaN/inf 直接报错。'''
    if bins < 2:
        raise ValueError('bins 至少为 2，否则反量化会除零')
    if not math.isfinite(c):
        raise ValueError('坐标必须是有限数: %r' % (c,))
    q = int(round(max(0.0, min(1.0, c)) * (bins - 1)))
    return max(0, min(bins - 1, q))


def dequantize(q, bins=BINS):
    '''桶号 -> [0,1] 坐标，误差上界 1/(2*(bins-1))。'''
    if bins < 2 or not 0 <= q <= bins - 1:
        raise ValueError('桶号越界或 bins 非法: %r / %r' % (q, bins))
    return q / (bins - 1)


def canon_box(box):
    '''任意角点顺序 -> 唯一表示（x1<=x2 且 y1<=y2），4 种写法收敛成 1 种。'''
    x1, y1, x2, y2 = box
    return (min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2))


def area2(poly):
    '''鞋带公式的两倍有向面积，正数表示逆时针。'''
    s = 0.0
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return s


def canon_polygon(poly):
    '''去相邻重复点 -> 逆时针 -> 以字典序最小顶点为起点，2K 种写法收敛成 1 种。'''
    pts = []
    for p in poly:
        if not pts or tuple(p) != pts[-1]:
            pts.append(tuple(p))
    if len(pts) > 1 and pts[0] == pts[-1]:
        pts.pop()
    if len(pts) < 3:
        raise ValueError('多边形至少需要 3 个不重复顶点: %r' % (poly,))
    if area2(pts) < 0:
        pts = [pts[0]] + pts[:0:-1]
    k = min(range(len(pts)), key=lambda i: pts[i])
    return tuple(pts[k:] + pts[:k])


def rle_encode(bits):
    '''二值掩码（行优先展平）-> 段长；约定第 0 段是 0 的个数，前导 1 补长度 0。'''
    if not bits:
        return ()
    counts = []
    cur = bits[0]
    if cur == 1:
        counts.append(0)
    run = 0
    for b in bits:
        if b == cur:
            run += 1
        else:
            counts.append(run)
            cur = b
            run = 1
    counts.append(run)
    return tuple(counts)


def rle_decode(counts, total=None):
    '''段长 -> 二值掩码；total 给定时右侧补 0，超出尺寸则报错。'''
    bits = []
    val = 0
    for c in counts:
        if c < 0:
            raise ValueError('RLE 段长不能为负: %r' % (c,))
        bits.extend([val] * c)
        val ^= 1
    if total is not None:
        if len(bits) > total:
            raise ValueError('RLE 解出 %d 位，超过掩码尺寸 %d' % (len(bits), total))
        bits.extend([0] * (total - len(bits)))
    return bits


def prim_to_tokens(kind, geom):
    '''一个几何原语 -> 结构 token 块：标签 + 顶点数或 RLE + 坐标 token + 结束符。'''
    if kind == 'mask':
        return [TAGS['mask']] + ['<r%d>' % c for c in geom] + [CLOSE]
    if kind == 'polygon':
        pts = canon_polygon(geom)
        flat = [v for p in pts for v in p]
        head = [TAGS['polygon'], '<k%d>' % len(pts)]
        return head + ['<c%d>' % quantize(v) for v in flat] + [CLOSE]
    if kind not in ARITY:
        raise ValueError('未知原语类型: %r' % (kind,))
    box = canon_box(geom) if kind == 'box' else tuple(geom)
    return [TAGS[kind]] + ['<c%d>' % quantize(v) for v in box] + [CLOSE]


def encode(text_tokens, prims):
    '''文本 token 与所有原语块拼成一条混合序列，它就是生成问题里的 x。'''
    seq = list(text_tokens)
    for kind, geom in prims:
        seq.extend(prim_to_tokens(kind, geom))
    return seq


def _read_block(tokens, i):
    '''从 i 往后读到结束符，返回 (块体, 下一位置)；缺结束符说明序列被截断。'''
    j = i
    while j < len(tokens) and tokens[j] != CLOSE:
        j += 1
    if j >= len(tokens):
        raise ValueError('原语块缺少结束符 %s' % CLOSE)
    return tokens[i:j], j + 1


def parse_prim(tag, body):
    '''把块体还原成 (类型, 几何量)，顺带做结构合法性检查。'''
    if tag == TAGS['mask']:
        counts = []
        for t in body:
            if not (t.startswith('<r') and t.endswith('>')):
                raise ValueError('mask 块里出现非 RLE token: %r' % (t,))
            counts.append(int(t[2:-1]))
        return ('mask', tuple(counts))
    k_tok = None
    if tag == TAGS['polygon']:
        if not body or not (body[0].startswith('<k') and body[0].endswith('>')):
            raise ValueError('polygon 块必须以顶点数 token 开头')
        k_tok = int(body[0][2:-1])
        body = body[1:]
    nums = []
    for t in body:
        if not (t.startswith('<c') and t.endswith('>')):
            raise ValueError('坐标块里出现非坐标 token: %r' % (t,))
        nums.append(int(t[2:-1]))
    if len(nums) % 2:
        raise ValueError('%s 的坐标个数必须是偶数，实际 %d' % (tag, len(nums)))
    vals = [dequantize(q) for q in nums]
    if tag == TAGS['point']:
        if len(vals) != 2:
            raise ValueError('point 必须恰好 2 个坐标')
        return ('point', tuple(vals))
    if tag == TAGS['box']:
        if len(vals) != 4:
            raise ValueError('box 必须恰好 4 个坐标')
        return ('box', canon_box(vals))
    if k_tok != len(vals) // 2:
        raise ValueError('顶点数 token %r 与实际 %d 不符' % (k_tok, len(vals) // 2))
    pts = [(vals[k], vals[k + 1]) for k in range(0, len(vals), 2)]
    return ('polygon', canon_polygon(pts))


def decode(tokens):
    '''混合序列 -> (文本 token, 原语列表)，即约束解码之后的反解步骤。'''
    text, prims = [], []
    by_tag = {}
    for k in TAGS:
        by_tag[TAGS[k]] = k
    i = 0
    while i < len(tokens):
        t = tokens[i]
        if t in by_tag:
            body, i = _read_block(tokens, i + 1)
            prims.append(parse_prim(t, body))
        elif t == CLOSE:
            raise ValueError('多余的结束符 %s' % CLOSE)
        else:
            text.append(t)
            i += 1
    return text, prims


def budget(prims):
    '''token 预算：point 4、box 6、polygon 3+2K、mask 2+R（R 为 RLE 段数）。'''
    n = 0
    for kind, geom in prims:
        if kind == 'mask':
            n += 2 + len(geom)
        elif kind == 'polygon':
            n += 3 + 2 * len(geom)
        elif kind == 'box':
            n += 6
        elif kind == 'point':
            n += 4
        else:
            raise ValueError('未知原语类型: %r' % (kind,))
    return n


class BigramLM:
    '''玩具语言模型：p(x_t | x 的前缀) 只依赖上一个 token，用来演示统一 NLL。'''

    def __init__(self, alpha=0.5):
        self.alpha = alpha
        self.vocab = set()
        self.pair = {}
        self.uni = {}

    def fit(self, seqs):
        for s in seqs:
            prev = '<bos>'
            self.vocab.add(prev)
            for t in s:
                self.vocab.add(t)
                self.pair[(prev, t)] = self.pair.get((prev, t), 0) + 1
                self.uni[prev] = self.uni.get(prev, 0) + 1
                prev = t
            self.pair[(prev, '<eos>')] = self.pair.get((prev, '<eos>'), 0) + 1
            self.vocab.add('<eos>')

    def prob(self, prev, nxt):
        v = len(self.vocab)
        num = self.pair.get((prev, nxt), 0) + self.alpha
        den = self.uni.get(prev, 0) + self.alpha * v
        return num / den


def masked_nll(tokens, model, loss_mask=None):
    '''-sum_t m_t log p(x_t | x 的前缀)；loss_mask 用来跳过 prompt 段。'''
    total = 0.0
    kept = 0
    prev = '<bos>'
    for i, t in enumerate(tokens):
        if loss_mask is None or loss_mask[i]:
            total -= math.log(max(model.prob(prev, t), 1e-12))
            kept += 1
        prev = t
    return total, kept


def main():
    # 1) 量化误差上界 |c - dequantize(quantize(c))| <= 1/(2*(BINS-1))
    worst = 0.0
    for i in range(2001):
        for c in (i / 2000.0, 1.0 - i / 2000.0):
            worst = max(worst, abs(c - dequantize(quantize(c))))
    bound = 1.0 / (2 * (BINS - 1))
    tol = bound + 1e-12                      # 浮点往返留一点余量
    assert worst <= tol, (worst, bound)
    print('量化误差 max=%.3e，上界 1/(2(B-1))=%.3e，换到 1000 像素图是 %.2f px'
          % (worst, bound, worst * 1000))

    # 2) 规范形把等价写法收敛成 1 种：box 有 4 种角点顺序，K 边形有 2K 种写法
    box = (0.8, 0.7, 0.2, 0.1)
    orders = ((0, 1, 2, 3), (2, 1, 0, 3), (0, 3, 2, 1), (2, 3, 0, 1))
    assert len({canon_box(tuple(box[k] for k in o)) for o in orders}) == 1
    poly = ((0.4, 0.1), (0.9, 0.5), (0.4, 0.9), (0.1, 0.5))
    forms = set()
    for k in range(len(poly)):
        rot = poly[k:] + poly[:k]
        forms.add(canon_polygon(rot))
        forms.add(canon_polygon(tuple(reversed(rot))))
    print('多边形等价写法 %d 种，规范化后 %d 种' % (2 * len(poly), len(forms)))
    assert len(forms) == 1, forms

    # 3) 文本 + 四种原语的混合序列往返，长度与预算函数一致
    bits = [0, 0, 1, 1, 1, 0, 0, 0, 1]
    prims = [
        ('point', (0.1234, 0.8765)),
        ('box', (0.8, 0.7, 0.2, 0.1)),
        ('polygon', ((0.4, 0.1), (0.9, 0.5), (0.4, 0.9), (0.1, 0.5))),
        ('mask', rle_encode(bits)),
    ]
    seq = encode(['猫', '在', '左上'], prims)
    text, back = decode(seq)
    assert text == ['猫', '在', '左上'] and len(back) == 4
    assert len(seq) == 3 + budget(prims), (len(seq), budget(prims))
    assert abs(back[0][1][0] - 0.1234) <= tol and abs(back[0][1][1] - 0.8765) <= tol
    want_box = (0.2, 0.1, 0.8, 0.7)
    assert max(abs(a - b) for a, b in zip(back[1][1], want_box)) <= tol
    want_poly = canon_polygon(prims[2][1])
    assert len(back[2][1]) == len(want_poly)
    for got, want in zip(back[2][1], want_poly):
        assert max(abs(got[0] - want[0]), abs(got[1] - want[1])) <= tol
    assert rle_decode(back[3][1], len(bits)) == bits
    print('混合序列 %d token = 文本 3 + 原语 %d；mask RLE %s 只要 %d token，稠密栅格要 %d'
          % (len(seq), budget(prims), tuple(rle_encode(bits)),
             2 + len(rle_encode(bits)), 2 + len(bits)))

    # 4) 统一自回归 NLL：p(x) 是全部 token 的联合，loss_mask 只跳过 prompt 段
    lm = BigramLM(alpha=0.5)
    lm.fit([seq, encode(['狗', '在', '右下'], prims[:2])])
    nll_all, n_all = masked_nll(seq, lm)
    loss_mask = [False, False, False] + [True] * (len(seq) - 3)
    nll_ans, n_ans = masked_nll(seq, lm, loss_mask)
    assert n_all == len(seq) and n_ans == len(seq) - 3 and nll_ans <= nll_all
    print('统一 NLL：全序列 %.3f（%d token），只算答案段 %.3f（%d token）'
          % (nll_all, n_all, nll_ans, n_ans))

    # 5) 边界：越界坐标 clamp、截断序列被拒、退化多边形被拒、全 0/全 1 掩码
    assert quantize(-0.5) == 0 and quantize(1.5) == BINS - 1
    assert rle_decode(rle_encode([0] * 6), 6) == [0] * 6
    assert rle_decode(rle_encode([1] * 3), 3) == [1] * 3
    bad_seqs = [seq[:-1], ['<box>', '<c10>', '<c20>', '<c30>', CLOSE]]
    for bad in bad_seqs:
        try:
            decode(bad)
        except ValueError as exc:
            print('非法序列被拒绝: %s' % exc)
            continue
        raise AssertionError('非法输入应当报错: %r' % (bad,))
    try:
        canon_polygon(((0.1, 0.1), (0.1, 0.1), (0.2, 0.2)))
    except ValueError as exc:
        print('退化多边形被拒绝: %s' % exc)
    else:
        raise AssertionError('退化多边形应当报错')
    print('边界用例全部通过：clamp、截断、退化多边形、空白掩码')


if __name__ == '__main__':
    main()
